    'Process mapping, time study, 5S review': { bn: 'প্রক্রিয়া মানচিত্র, সময় সমীক্ষা, 5S পর্যালোচনা', zh: '流程图、时间研究、5S评估', ar: 'رسم العمليات ودراسة الوقت ومراجعة 5S', de: 'Prozessmapping, Zeitstudie, 5S-Bewertung' },
    'Mechanical Design': { bn: 'মেকানিক্যাল ডিজাইন', zh: '机械设计', ar: 'التصميم الميكانيكي', de: 'Konstruktion' },
    'Manufacturing Engineering': { bn: 'ম্যানুফ্যাকচারিং ইঞ্জিনিয়ারিং', zh: '制造工程', ar: 'هندسة التصنيع', de: 'Fertigungstechnik' },
    'Industrial Automation': { bn: 'শিল্প অটোমেশন', zh: '工业自动化', ar: 'الأتمتة الصناعية', de: 'Industrielle Automatisierung' },
    'CAD / Modeling': { bn: 'CAD / মডেলিং', zh: 'CAD / 建模', ar: 'CAD / النمذجة', de: 'CAD / Modellierung' },
