    'Score: 115 | Recorded on 22 March 2026': { bn: 'স্কোর: ১১৫ | রেকর্ডের তারিখ: ২২ মার্চ ২০২৬', zh: '分数：115 | 记录日期：2026年3月22日', ar: 'النتيجة: 115 | تاريخ التسجيل: 22 مارس 2026', de: 'Ergebnis: 115 | Eingetragen am 22. März 2026' },
